@Service
class OrderService {
    private static final Logger log = LoggerFactory.getLogger(OrderService.class);

    public void process(Order order) {
        log.info("Processing order: {}", order.id());

        // Step 2: Isolate - add logging to narrow down failure point
        if (order.price() <= 0) {
            log.error("Invalid price detected: {}", order.price());
            throw new IllegalArgumentException("Price must be positive");
        }

        var discount = calculateDiscount(order);
        log.debug("Calculated discount: {}", discount); // Step 3: Hypothesis - verify discount logic

        var finalPrice = order.price() - discount;
        log.info("Final price: {}", finalPrice);
    }
}

