// Bug: Orders over $100 aren't getting discounts
@Service
class OrderService {
    public double calculateTotal(Order order) {
        var subtotal = order.price() * order.quantity();

        // Explaining to duck: "Okay, so if the subtotal is over 100..."
        if (subtotal > 100) {
            var discount = subtotal * 0.10;
            // "...I calculate a 10 percent discount..."

            return subtotal - discount;
            // "...and return the discounted price.
            //   Wait. I'm returning here. What about the shipping?
            //   Oh! The shipping code below never runs for large orders!"
        }

        var shipping = calculateShipping(order);
        return subtotal + shipping; // BUG: large orders skip shipping
    }
}

// Fixed version after duck debugging
public double calculateTotal(Order order) {
    var subtotal = order.price() * order.quantity();
    var discount = subtotal > 100 ? subtotal * 0.10 : 0.0;
    var shipping = calculateShipping(order);
    return subtotal - discount + shipping;
}

