class OrderService {
    private final CustomerRepository customerRepo;
    private final InventoryService inventoryService;

    public void processOrder(Long customerId, String productId) {
        // Assumption 1: Customer exists in database
        var customer = customerRepo.findById(customerId)
            .orElseThrow(() -> new NotFoundException("Customer not found"));

        // Assumption 2: Inventory service returns non-null
        var available = inventoryService.checkStock(productId);
        if (available == null) { // Explicitly check the assumption
            throw new IllegalStateException("Inventory service returned null");
        }

        // Assumption 3: Available means quantity > 0
        if (available <= 0) {
            throw new OutOfStockException("Product unavailable");
        }

        // Each assumption is now verified with explicit checks
        createOrder(customer, productId);
    }
}

