// Bug report: GET /orders/{id} returns 500 Internal Server Error

@RestController
class OrderController {
    private static final Logger log = LoggerFactory.getLogger(OrderController.class);
    private final OrderService orderService;

    @GetMapping("/orders/{id}")
    public ResponseEntity<Order> getOrder(@PathVariable Long id) {
        // Step 1: Add logging to reproduce and trace execution
        log.info("Received request for order ID: {}", id);

        try {
            // Step 2: Isolate - check if service call is the problem
            var order = orderService.findById(id);
            log.debug("Service returned order: {}", order);

            // Step 3: Check assumptions - is order ever null?
            if (order == null) {
                log.warn("Service returned null for order ID: {}", id);
                return ResponseEntity.notFound().build();
            }

            return ResponseEntity.ok(order);

        } catch (Exception e) {
            // Step 4: Log full exception details to understand the failure
            log.error("Failed to retrieve order: {}", id, e);
            throw e;
        }
    }
}
